/**
 * Справка TubeStudio — единый источник текста.
 * Используется страницей /help и генератором Word-документации (scripts/build-docs.ts).
 * Разметка внутри строк: **жирный**, `код`.
 */
export type HelpSection = {
  id: string;
  title: string;
  icon: string;          // имя иконки lucide (для веба)
  route?: string;        // где в программе
  short: string;         // одной фразой
  what: string;          // простыми словами
  analogy?: string;      // «это как…»
  when?: string[];       // когда пользоваться
  steps?: string[];      // как пользоваться
  fields?: [string, string][]; // поле → что значит
  example?: { title: string; input: string; output: string };
  results?: [string, string][]; // что увидите → как читать
  tips?: string[];
  problems?: [string, string][]; // проблема → что делать
  codeExample?: { title: string; language: string; code: string };
  details?: string[]; // точная методика и ограничения, раскрываются отдельно
  cost?: string;         // что тратит
};
export type HelpGroup = { title: string; sections: HelpSection[] };

