export const HELP_SECTIONS = HELP.flatMap((g) => g.sections);
/** Маршрут программы → основная глава справки */
export const helpIdForRoute = (route: string) => (route === "/help" ? "help" : HELP_SECTIONS.find((s) => s.route === route)?.id);
